<?php
require_once __DIR__.'/../includes/authorization.php';require_role('admin');require_once __DIR__.'/../includes/Repositories/UserRepository.php';
$repo=new UserRepository();$errors=[];$me=(int)$_SESSION['user_id'];
if(is_post()){if(!verify_csrf()){flash('error','Sesi formulir tidak valid.');redirect(page_url('admin-users'));}$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';if(!$id||!in_array($status,['active','inactive','suspended'],true)){flash('error','Data status tidak valid.');redirect(page_url('admin-users'));}$user=$repo->findById((int)$id);if(!$user){flash('error','User tidak ditemukan.');redirect(page_url('admin-users'));}if((int)$id===$me&&$status!=='active'){flash('error','Admin yang sedang login tidak boleh menonaktifkan dirinya sendiri.');redirect(page_url('admin-users'));}try{$repo->updateAdmin((int)$id,['full_name'=>$user['full_name'],'username'=>$user['username'],'whatsapp'=>$user['whatsapp'],'email'=>$user['email'],'role'=>$user['role'],'status'=>$status,'password'=>'']);flash('success','Status pengguna diperbarui.');}catch(Throwable $e){flash('error','Status pengguna gagal diperbarui.');}redirect(page_url('admin-users'));}
$users=$repo->all();$pageTitle='Kelola Pengguna';require __DIR__.'/../includes/header.php';
?>
<section class="section-padding page-section"><div class="container"><div class="page-toolbar d-flex justify-content-between align-items-center gap-2 flex-wrap"><?=back_link('admin-dashboard','Kembali ke dashboard admin')?><a class="btn btn-primary btn-sm" href="<?=e(page_url('admin-user-form'))?>"><i class="bi bi-person-plus me-1"></i>Tambah pengguna</a></div><div class="section-heading mb-4"><span class="eyebrow">Admin · Pengguna</span><h2>Kelola <em>pengguna.</em></h2><p class="text-muted">Kelola customer, seller, dan admin. Seller dibuat dari modul ini.</p></div><?php if($errors):?><div class="alert alert-danger"><?=implode('<br>',array_map('e',$errors))?></div><?php endif;?><div class="glass-card p-3"><div class="table-responsive"><table class="table align-middle mb-0 admin-table"><thead><tr><th>User</th><th>Kontak</th><th>Role</th><th>Status</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['full_name'])?></strong><div class="small text-muted">@<?=e($u['username'])?></div></td><td><div><?=e($u['email'])?></div><small class="text-muted"><?=e($u['whatsapp'])?></small></td><td><span class="role-pill role-<?=e($u['role'])?>"><?=e($u['role'])?></span></td><td><span class="status-pill status-<?=e($u['status'])?>"><?=e($u['status'])?></span></td><td><small class="text-muted"><?=e($u['created_at'])?></small></td><td><div class="d-flex gap-2 flex-wrap"><a class="btn btn-soft btn-sm" href="<?=e(page_url('admin-user-edit',['id'=>$u['id']]))?>"><i class="bi bi-pencil me-1"></i>Edit</a><?php if((int)$u['id']!==$me):?><form method="post" class="m-0"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=intval($u['id'])?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'inactive':'active'?>"><button class="btn btn-outline-secondary btn-sm"><?=$u['status']==='active'?'Nonaktifkan':'Aktifkan'?></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div><p class="small text-muted mt-3 mb-0">Tidak ada hard delete user karena user dapat terhubung ke produk, order, dan ulasan. Gunakan status inactive/suspended sebagai penghapusan logis.</p></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
